/// <summary>
/// PaffH 02.02.21
/// </summary>
/// <param name = "_MenuBase">SysDictMenu</param>
/// <returns>SysDictMenu</returns>
public SysDictMenu parmMenuBase(SysDictMenu _MenuBase = menuBase)
{
    menuBase = _MenuBase;
    return menuBase;
}

/// <summary>
/// PaffH 02.02.21
/// </summary>
/// <param name = "_MenuItemNameBase">str</param>
/// <returns>str</returns>
public str parmMenuItemNameBase(str _MenuItemNameBase = menuItemNameBase)
{
    menuItemNameBase = _MenuItemNameBase;
    return menuItemNameBase;
}

/// <summary>
/// PaffH 02.02.21
/// </summary>
