/// <summary>
/// PaffH 02.02.21
/// </summary>
/// <param name = "_menuItemTypeBase">MenuItemType</param>
/// <param name = "_menuItemNameBase">str</param>
/// <returns>NDXAOTHelperMenu</returns>
public static NDXAOTHelperMenu construct(MenuItemType _menuItemTypeBase, str _menuItemNameBase)
{
    NDXAOTHelperMenu nDXAOTHelperMenu =  new NDXAOTHelperMenu();
    nDXAOTHelperMenu.parmTreeNodeBase(TreeNode::findNode(#MenusPath));
    nDXAOTHelperMenu.parmMenuBase(SysDictMenu::newTreeNode(nDXAOTHelperMenu.parmTreeNodeBase()));
    nDXAOTHelperMenu.parmMenuItemTypeBase(_menuItemTypeBase);
    nDXAOTHelperMenu.parmMenuItemNameBase(_menuItemNameBase);

    return nDXAOTHelperMenu;
}

/// <summary>
/// PaffH 02.02.21
/// </summary>
/// <param name = "_menuItemTypeBase">MenuItemType</param>
/// <param name = "_menuItemNameBase">str</param>
