public static NDXAOTHelperMenu constructTiles(MenuItemType _menuItemTypeBase, str _menuItemNameBase)
{
    NDXAOTHelperMenu nDXAOTHelperMenu =  new NDXAOTHelperMenu();
    nDXAOTHelperMenu.parmTreeNodeBase(TreeNode::findNode(#TilesPath));
    nDXAOTHelperMenu.parmMenuBase(SysDictMenu::newTreeNode(nDXAOTHelperMenu.parmTreeNodeBase()));
    nDXAOTHelperMenu.parmMenuItemTypeBase(_menuItemTypeBase);
    nDXAOTHelperMenu.parmMenuItemNameBase(_menuItemNameBase);

    return nDXAOTHelperMenu;
}

/// <summary>
/// PaffH 02.02.21
/// find name of menuItem
/// </summary>
/// <param name = "_cMenu">SysDictMenu to search in</param>
/// <param name = "type">MenuItemType (default = menuItemTypeBase)</param>
/// <param name = "menuItemName">name of the menuItem to search for (default = menuItemNameBase)</param>
/// <returns>MenuItemName found</returns>
public boolean iterateMenus(SysDictMenu _cMenu = this.menuBase, MenuItemType type = this.menuItemTypeBase, str menuItemName = this.menuItemNameBase)
{
    SysMenuEnumerator menuEnum = _cMenu.getEnumerator();
    SysDictMenu subMenu;
    str menuItemName2;

    while (menuEnum.moveNext())
    {
        subMenu = menuEnum.current();
        if (subMenu.isMenu() || subMenu.isMenuReference())
        {
            this.iterateMenus(subMenu, type, menuItemName);
        }
        if (subMenu.isMenuItem())
        {
            if (subMenu.menuItem().type() == type)
            {
                menuItemName2 = subMenu.menuItem().name();
                if (menuItemName2 == menuItemName)
                {
                    return true;
                }
            }
        }
    }
    return false;
}
